begin
  for item in select value from jsonb_array_elements($enem_review$[{"slug": "enem-2022", "number": 9, "id": "d2ea0ee8-f04f-48d3-a11b-cd29324401b4", "before": {"text": "Odiscurso da jornalista traz questionamentos sobre a relação da conquista da skatista com a"}, "after": {"text": "O discurso da jornalista traz questionamentos sobre a relação da conquista da skatista com a"}, "reasons": ["Espaçamento/quebra de verso: Odiscurso"]}, {"slug": "enem-2022", "number": 24, "id": "99d26174-8401-4592-874d-37c34599ff48", "before": {"text": "Otexto é exemplar de um gênero discursivo que cumpre a função social de"}, "after": {"text": "O texto é exemplar de um gênero discursivo que cumpre a função social de"}, "reasons": ["Espaçamento/quebra de verso: Otexto"]}, {"slug": "enem-2022", "number": 73, "id": "ce24518e-e232-4df6-be51-8fc94d39fa41", "before": {"support": "Olhar o Brasil e não ver o sertão\n\nÉ como negar o queijo com a faca na mão\n\nEsse gigante em movimento\n\nMovido a tijolo e cimento\n\nPrecisa de arroz com feijão\n\nQue tenha comida na mesa\n\nQue agradeça sempre a grandeza\n\nDe cada pedaço de pãoAgradeça a Clemente\n\nQue leva a sementeEm seu embornal\n\nZezé e o penoso balé\n\nDe pisar no cacau\n\nMaria que amanhece o dia\n\nLá no milharal."}, "after": {"support": "Olhar o Brasil e não ver o sertão\n\nÉ como negar o queijo com a faca na mão\n\nEsse gigante em movimento\n\nMovido a tijolo e cimento\n\nPrecisa de arroz com feijão\n\nQue tenha comida na mesa\n\nQue agradeça sempre a grandeza\n\nDe cada pedaço de pão\nAgradeça a Clemente\n\nQue leva a semente\nEm seu embornal\n\nZezé e o penoso balé\n\nDe pisar no cacau\n\nMaria que amanhece o dia\n\nLá no milharal."}, "reasons": ["Espaçamento/quebra de verso: sementeEm", "Espaçamento/quebra de verso: pãoAgradeça"]}, {"slug": "enem-2022", "number": 171, "id": "8a0b7237-759a-4ae6-bca2-3c01facd55b2", "before": {"support": "Em uma sala de cinema, para garantir que os espectadores vejam toda a imagem projetada na tela, a disposição das poltronas deve obedecer à norma técnica daAssociação Brasileira de Normas Técnicas (ABNT), que faz as seguintes indicações:\n\n• Distância mínima (Dmin) entre a tela de projeção e o encosto da poltrona da primeira fileira deve ser de, pelo menos, 60 por cento da largura (L) da tela.\n\n• Distância máxima (Dmax entre a tela de projeção e o encosto da poltrona da última fileira deve ser o dobro da largura (L) da tela, sendo aceitável uma distância de até 2,9 vezes a largura (L) da tela.\n\nPara o espaçamento entre as fileiras de poltronas, é considerada a distância de 1 metro entre os encostos de poltronas em duas fileiras consecutivas.\n\nUma sala de cinema, cuja largura da tela mede 12 metros, está montada em conformidade com as normas da ABNT e tem suas dimensões especificadas na figura.\n\nPretende-se ampliar essa sala, mantendo-se na mesma posição a tela e todas as poltronas já instaladas, ampliando-se ao máximo a sala para os fundos (área de instalação de novas poltronas), respeitando-se o limite aceitável da norma da ABNT. A intenção é aumentar, ao máximo, a quantidade de poltronas da sala, instalando-se novas unidades, iguais às já instaladas.\n\nDisponível em: www.ctav.gov.br. Acesso em: 14 nov. 2013."}, "after": {"support": "Em uma sala de cinema, para garantir que os espectadores vejam toda a imagem projetada na tela, a disposição das poltronas deve obedecer à norma técnica da Associação Brasileira de Normas Técnicas (ABNT), que faz as seguintes indicações:\n\n• Distância mínima (Dmin) entre a tela de projeção e o encosto da poltrona da primeira fileira deve ser de, pelo menos, 60 por cento da largura (L) da tela.\n\n• Distância máxima (Dmax entre a tela de projeção e o encosto da poltrona da última fileira deve ser o dobro da largura (L) da tela, sendo aceitável uma distância de até 2,9 vezes a largura (L) da tela.\n\nPara o espaçamento entre as fileiras de poltronas, é considerada a distância de 1 metro entre os encostos de poltronas em duas fileiras consecutivas.\n\nUma sala de cinema, cuja largura da tela mede 12 metros, está montada em conformidade com as normas da ABNT e tem suas dimensões especificadas na figura.\n\nPretende-se ampliar essa sala, mantendo-se na mesma posição a tela e todas as poltronas já instaladas, ampliando-se ao máximo a sala para os fundos (área de instalação de novas poltronas), respeitando-se o limite aceitável da norma da ABNT. A intenção é aumentar, ao máximo, a quantidade de poltronas da sala, instalando-se novas unidades, iguais às já instaladas.\n\nDisponível em: www.ctav.gov.br. Acesso em: 14 nov. 2013."}, "reasons": ["Espaçamento/quebra de verso: daAssociação"]}, {"slug": "enem-2023", "number": 4, "id": "4169ebc4-2efe-4be7-a47a-c1f52e811ddb", "before": {"support": "## Things We Carry on the Sea\n\nWe carry tears in our eyes: good-bye father, good-bye mother\n\nWe carry soil in small bags: may home never fade in our hearts\n\nWe carry carnage of mining, droughts, floods, genocides\n\nWe carry dust of our families and neighbors incinerated in mushroom clouds\n\nWe carry our islands sinking under the sea\n\nWe carry our hands, feet, bones, hearts and best minds for a new life\n\nWe carry diplomas: medicine, engineer, nurse, education, math, poetry, even if they mean nothing to the other shore\n\nWe carry railroads, plantations, laundromats, bodegas, taco trucks, farms, factories, nursing homes, hospitals, schools, temples... built on [our ancestors’ backs\n\nWe carry old homes along the spine, new dreams in our chestsWe carry yesterday, today and tomorrowWe’re orphans of the wars forced upon us\n\nWe’re refugees of the sea rising from industrial wastes And we carry our mother tongues\n\n[...]\n\nAs we drift... in our rubber boats... from shore... to shore... to shore...\n\nPING, W. Disponível em: https://poets.org. Acesso em: 1 jun. 2023 (fragmento)."}, "after": {"support": "## Things We Carry on the Sea\n\nWe carry tears in our eyes: good-bye father, good-bye mother\n\nWe carry soil in small bags: may home never fade in our hearts\n\nWe carry carnage of mining, droughts, floods, genocides\n\nWe carry dust of our families and neighbors incinerated in mushroom clouds\n\nWe carry our islands sinking under the sea\n\nWe carry our hands, feet, bones, hearts and best minds for a new life\n\nWe carry diplomas: medicine, engineer, nurse, education, math, poetry, even if they mean nothing to the other shore\n\nWe carry railroads, plantations, laundromats, bodegas, taco trucks, farms, factories, nursing homes, hospitals, schools, temples... built on [our ancestors’ backs\n\nWe carry old homes along the spine, new dreams in our chests\nWe carry yesterday, today and tomorrow\nWe’re orphans of the wars forced upon us\n\nWe’re refugees of the sea rising from industrial wastes And we carry our mother tongues\n\n[...]\n\nAs we drift... in our rubber boats... from shore... to shore... to shore...\n\nPING, W. Disponível em: https://poets.org. Acesso em: 1 jun. 2023 (fragmento)."}, "reasons": ["Espaçamento/quebra de verso: chestsWe", "Espaçamento/quebra de verso: tomorrowWe"]}, {"slug": "enem-2023", "number": 13, "id": "3ddbcfaa-4fee-44e6-a796-a3dd7e9141d4", "before": {"support": "## Sombras de reis barbudos\n\nJosé J. Veiga\n\nEnquanto estivemos entretidos com os urubus outras coisas andaram acontecendo na cidade. A Companhia baixou novas proibições, umas inteiramente bobocas, só pelo prazer de proibir (ninguém podia cuspir pra cima, nem carregar água em jacá, nem tapar o sol com peneira, como se todo mundo estivesse abusando dessas esquisitices); mas outras bem irritantes, como a de pular muro pra cortar caminho, tática que quase todo mundo que não sofria de reumatismo vinha adotando ultimamente, principalmente os meninos. E não confiando na proibição só, nem na força dos castigos, que eram rigorosos, a Companhia ainda mandou fincar cacos de garrafa nos muros. Achei isso um exagero, e comentei o assunto com mamãe. Meu pai ouviulá do quarto e veio explicar. Disse que em épocas normais bastava uma coisa ou outra; mas agora a Companhia não podia admitir nenhuma brecha em suas ordens; se alguém desobedecesse à proibição podia se cortar nos cacos; se alguém conseguisse pular um muro quebrando o corte de alguns cacos, ou jogando um couro por cima, era apanhado pela proibição, nhoc — e fez o gesto de quem torce o pescoço de um frango."}, "after": {"support": "## Sombras de reis barbudos\n\nJosé J. Veiga\n\nEnquanto estivemos entretidos com os urubus outras coisas andaram acontecendo na cidade. A Companhia baixou novas proibições, umas inteiramente bobocas, só pelo prazer de proibir (ninguém podia cuspir pra cima, nem carregar água em jacá, nem tapar o sol com peneira, como se todo mundo estivesse abusando dessas esquisitices); mas outras bem irritantes, como a de pular muro pra cortar caminho, tática que quase todo mundo que não sofria de reumatismo vinha adotando ultimamente, principalmente os meninos. E não confiando na proibição só, nem na força dos castigos, que eram rigorosos, a Companhia ainda mandou fincar cacos de garrafa nos muros. Achei isso um exagero, e comentei o assunto com mamãe. Meu pai ouviu lá do quarto e veio explicar. Disse que em épocas normais bastava uma coisa ou outra; mas agora a Companhia não podia admitir nenhuma brecha em suas ordens; se alguém desobedecesse à proibição podia se cortar nos cacos; se alguém conseguisse pular um muro quebrando o corte de alguns cacos, ou jogando um couro por cima, era apanhado pela proibição, nhoc — e fez o gesto de quem torce o pescoço de um frango."}, "reasons": ["Espaçamento/quebra de verso: ouviulá"]}, {"slug": "enem-2023", "number": 39, "id": "23d74e26-cf9c-40ce-a5f7-bcaaa4bd3d24", "before": {"support": "## TEXTO 1\n\nAlegria, alegria (fragmento)\n\nCaetano Veloso\n\nO sol nas bancas de revista\n\nMe enche de alegria e preguiça\n\nQuem lê tanta notícia\n\nEu vouPor entre fotos e nomes\n\nOs olhos cheios de cores\n\nO peito cheio de amores vãos\n\nEu vou\n\nPor que não, por que não?\n\n## TEXTO 2\n\nAnjos tronchos (fragmento)\n\nCaetano Veloso\n\nUns anjos tronchos do Vale do Silício\n\nDesses que vivem no escuro em plena luz\n\nDisseram vai ser virtuoso no vício\n\nDas telas dos azuis mais do que azuis\n\nAgora a minha história é um denso algoritmo\n\nQue vende venda a vendedores reais\n\nNeurônios meus ganharam novo outro ritmo\n\nE mais, e mais, e mais, e mais, e mais\n\nVELOSO, C. Alegria, alegria. Rio de Janeiro: Polygram, 1990 (fragmento).\n\nVELOSO, C. Meu coco. Rio de Janeiro: Sony, 2021 (fragmento)."}, "after": {"support": "## TEXTO 1\n\nAlegria, alegria (fragmento)\n\nCaetano Veloso\n\nO sol nas bancas de revista\n\nMe enche de alegria e preguiça\n\nQuem lê tanta notícia\n\nEu vou\nPor entre fotos e nomes\n\nOs olhos cheios de cores\n\nO peito cheio de amores vãos\n\nEu vou\n\nPor que não, por que não?\n\n## TEXTO 2\n\nAnjos tronchos (fragmento)\n\nCaetano Veloso\n\nUns anjos tronchos do Vale do Silício\n\nDesses que vivem no escuro em plena luz\n\nDisseram vai ser virtuoso no vício\n\nDas telas dos azuis mais do que azuis\n\nAgora a minha história é um denso algoritmo\n\nQue vende venda a vendedores reais\n\nNeurônios meus ganharam novo outro ritmo\n\nE mais, e mais, e mais, e mais, e mais\n\nVELOSO, C. Alegria, alegria. Rio de Janeiro: Polygram, 1990 (fragmento).\n\nVELOSO, C. Meu coco. Rio de Janeiro: Sony, 2021 (fragmento)."}, "reasons": ["Espaçamento/quebra de verso: vouPor"]}, {"slug": "enem-2023", "number": 142, "id": "8fd72598-1b3f-43fd-9db9-0d2f9e74deab", "before": {"support": "Sejam a, b e c as medidas dos lados de um triângulo retângulo, tendo a como medida da hipotenusa. Esses valores a, b e c são, respectivamente, os diâmetros dos círculos C1, C2 e C3, como apresentados na figura.\n\nEssa construção assegura, pelo teorema de Pitágoras, que área de C1 é igual a área de C2 mais área de C3.\n\nUm professor de matemática era conhecedor dessa construção e, confraternizando com dois amigos em uma pizzaria onde são vendidas pizzas somente em formato de círculo, lançou um desafio: mesmo sem usar uminstrumento de medição, poderia afirmar com certeza se a área do círculo correspondente à pizza que ele pedisse era maior, igual ou menor do que a soma das áreas das pizzas dos dois amigos. Assim, foram pedidas três pizzas. O professor as dividiu ao meio e formou um triângulo com os diâmetros das pizzas, conforme indicado na figura.\n\nA partir da medida do ângulo alfa, o professor afirmou que a área de sua pizza é maior do que a soma das áreas das outras duas pizzas."}, "after": {"support": "Sejam a, b e c as medidas dos lados de um triângulo retângulo, tendo a como medida da hipotenusa. Esses valores a, b e c são, respectivamente, os diâmetros dos círculos C1, C2 e C3, como apresentados na figura.\n\nEssa construção assegura, pelo teorema de Pitágoras, que área de C1 é igual a área de C2 mais área de C3.\n\nUm professor de matemática era conhecedor dessa construção e, confraternizando com dois amigos em uma pizzaria onde são vendidas pizzas somente em formato de círculo, lançou um desafio: mesmo sem usar um instrumento de medição, poderia afirmar com certeza se a área do círculo correspondente à pizza que ele pedisse era maior, igual ou menor do que a soma das áreas das pizzas dos dois amigos. Assim, foram pedidas três pizzas. O professor as dividiu ao meio e formou um triângulo com os diâmetros das pizzas, conforme indicado na figura.\n\nA partir da medida do ângulo alfa, o professor afirmou que a área de sua pizza é maior do que a soma das áreas das outras duas pizzas."}, "reasons": ["Espaçamento/quebra de verso: uminstrumento"]}, {"slug": "enem-2023", "number": 151, "id": "cdbd11a7-520b-44bb-b1a1-d1dc3f28cac0", "before": {"text": "Onúmero mínimo de salas que deverão ser construídas é"}, "after": {"text": "O número mínimo de salas que deverão ser construídas é"}, "reasons": ["Espaçamento/quebra de verso: Onúmero"]}, {"slug": "enem-2024", "number": 4, "id": "002a9c31-02c1-456d-a63a-5593deed230b", "before": {"text": "A carta da editora Stephanie Allen-Nichols à escritoraAlice Walker tem o propósito de"}, "after": {"text": "A carta da editora Stephanie Allen-Nichols à escritora Alice Walker tem o propósito de"}, "reasons": ["Espaçamento/quebra de verso: escritoraAlice"]}, {"slug": "enem-2024", "number": 31, "id": "fc70b2ef-3f0d-4540-bcf5-55ee754c663e", "before": {"text": "Um estudo norte-americano analisou os efeitos da pandemia da covid-19 sobre a saúde mental e a manutenção da atividade física, revelando que um fator está diretamente ligado ao outro. De acordo com os dados, famílias de baixa renda foram mais impactadas pelo ciclo vicioso de falta de motivação e pelo sedentarismo. Diante da necessidade de distanciamento social e do início da quarentena, as opções de espaços seguros para exercícios físicos diminuíram, o que dificultou que as pessoas mantivessem seus níveis de atividade. Os dados evidenciaram que as pessoas mais ativas tinham melhor estado de saúde mental. As pessoas com menor renda tiveram mais dificuldade para manter os níveis de atividade física durante a pandemia, sendo aproximadamente duas vezes menos propensas a continuarem no mesmo ritmo de exercícios de antes da pandemia. Habitantes de áreas urbanas mostraram maior probabilidade de não conseguirem manter os níveis de atividade física semelhantes aos de pessoas que vivem em zonas rurais, onde há mais oportunidades de sair para espaços abertos.\r\nOtexto evidencia a perspectiva ampliada de saúde ao abordar criticamente a pandemia da covid-19 a partir do(a)"}, "after": {"text": "Um estudo norte-americano analisou os efeitos da pandemia da covid-19 sobre a saúde mental e a manutenção da atividade física, revelando que um fator está diretamente ligado ao outro. De acordo com os dados, famílias de baixa renda foram mais impactadas pelo ciclo vicioso de falta de motivação e pelo sedentarismo. Diante da necessidade de distanciamento social e do início da quarentena, as opções de espaços seguros para exercícios físicos diminuíram, o que dificultou que as pessoas mantivessem seus níveis de atividade. Os dados evidenciaram que as pessoas mais ativas tinham melhor estado de saúde mental. As pessoas com menor renda tiveram mais dificuldade para manter os níveis de atividade física durante a pandemia, sendo aproximadamente duas vezes menos propensas a continuarem no mesmo ritmo de exercícios de antes da pandemia. Habitantes de áreas urbanas mostraram maior probabilidade de não conseguirem manter os níveis de atividade física semelhantes aos de pessoas que vivem em zonas rurais, onde há mais oportunidades de sair para espaços abertos.\r\nO texto evidencia a perspectiva ampliada de saúde ao abordar criticamente a pandemia da covid-19 a partir do(a)"}, "reasons": ["Espaçamento/quebra de verso: Otexto"]}, {"slug": "enem-2024", "number": 33, "id": "37f755a4-bd63-4b07-bdec-704acd75f3a8", "before": {"text": "Tati Bernardi\r\nSempre passo nervoso quando leio minha crônica neste jornal e percebo que escapuliu a palavra “coisa” em alguma frase. Acontece que “coisa” está entre as coisas mais deliciosas do mundo.\r\nO primeiro banho da minha filha foi embalado pela minha voz dizendo, ao fundo, “cuidado, ela ainda é uma coisinha tão pequena”. “Viu só que amor? Nunca vi coisa assim”. O amor que não dá conta de explicação é “a coisa” em seu esplendor e excelência. “Alguma coisa acontece no meu coração” é a frase mais bonita que alguém já disse sobre São Paulo. E quando Caetano, citado aqui pela terceira vez pra defender a dimensão poética da coisa, diz “coisa linda”, nós sabemos que nenhuma palavra definiria de forma mais profunda e literária o quão bela e amada uma coisa pode ser.\r\n“Coisar” é verbo de quem está com pressa ou tem lapsos de memória. É pra quando “mexe qualquer coisa dentro doida”. E que coisa magnífica poder se expressar tal qual Caetano Veloso. Agora chega, porque “esse papo já tá qualquer coisa” e eu já tô “pra lá de Marrakech”.\r\nOrecurso utilizado na progressão textual para garantir a unidade temática dessa crônica é a"}, "after": {"text": "Tati Bernardi\r\nSempre passo nervoso quando leio minha crônica neste jornal e percebo que escapuliu a palavra “coisa” em alguma frase. Acontece que “coisa” está entre as coisas mais deliciosas do mundo.\r\nO primeiro banho da minha filha foi embalado pela minha voz dizendo, ao fundo, “cuidado, ela ainda é uma coisinha tão pequena”. “Viu só que amor? Nunca vi coisa assim”. O amor que não dá conta de explicação é “a coisa” em seu esplendor e excelência. “Alguma coisa acontece no meu coração” é a frase mais bonita que alguém já disse sobre São Paulo. E quando Caetano, citado aqui pela terceira vez pra defender a dimensão poética da coisa, diz “coisa linda”, nós sabemos que nenhuma palavra definiria de forma mais profunda e literária o quão bela e amada uma coisa pode ser.\r\n“Coisar” é verbo de quem está com pressa ou tem lapsos de memória. É pra quando “mexe qualquer coisa dentro doida”. E que coisa magnífica poder se expressar tal qual Caetano Veloso. Agora chega, porque “esse papo já tá qualquer coisa” e eu já tô “pra lá de Marrakech”.\r\nO recurso utilizado na progressão textual para garantir a unidade temática dessa crônica é a"}, "reasons": ["Espaçamento/quebra de verso: Orecurso"]}, {"slug": "enem-2024", "number": 42, "id": "5f988e1e-24a6-412a-830d-e263da8684a4", "before": {"text": "Oconjunto dessas práticas musicais demonstra que os instrumentos mencionados no texto"}, "after": {"text": "O conjunto dessas práticas musicais demonstra que os instrumentos mencionados no texto"}, "reasons": ["Espaçamento/quebra de verso: Oconjunto"]}, {"slug": "enem-2024", "number": 85, "id": "5b127611-319f-4cb8-ac9f-958f8ed57339", "before": {"text": "Há experiências de lutas sociais de reapropriação cultural da natureza que são movimentos emblemáticos, como a dos seringueiros no Brasil, que da luta sindical para a comercialização da borracha chegaram a inventar o conceito de reserva extrativista e estão avançando para um novo modo de produção, uma nova racionalidade produtiva, mostrando que é possível viver bem, e não apenas sobreviver, em harmonia com a natureza que habitam. O novo planeta que podemos imaginar é feito desses territórios produtivos que não são apenas economias de autossubsistência mas economias que potencializam a produtividade ecológica de seus territórios.\r\nOtexto expõe a possibilidade de uma nova racionalidade produtiva por meio de uma gestão territorial que se baseia na"}, "after": {"text": "Há experiências de lutas sociais de reapropriação cultural da natureza que são movimentos emblemáticos, como a dos seringueiros no Brasil, que da luta sindical para a comercialização da borracha chegaram a inventar o conceito de reserva extrativista e estão avançando para um novo modo de produção, uma nova racionalidade produtiva, mostrando que é possível viver bem, e não apenas sobreviver, em harmonia com a natureza que habitam. O novo planeta que podemos imaginar é feito desses territórios produtivos que não são apenas economias de autossubsistência mas economias que potencializam a produtividade ecológica de seus territórios.\r\nO texto expõe a possibilidade de uma nova racionalidade produtiva por meio de uma gestão territorial que se baseia na"}, "reasons": ["Espaçamento/quebra de verso: Otexto"]}, {"slug": "enem-2022", "number": 16, "id": "10a04da1-392b-4f56-94c6-baabef22da2f", "before": {"support_image": "/enem-2022/q016-support-1-1.png,/enem-2022/q016-support-1-2.png,/enem-2022/q016-support-1-3.png", "support": "MANUAL DE ORIENTAÇÃO\nO primeiro guia prático da Sociedade Brasileira de Pediatria para ajudar pais e pediatras no desafio de educar nativos digitais.\n\nTRABALHO DE BASE\n\nAté 2 anos: A criança não deve ser exposta passivamente às telas — TV, tablet, celular etc. —, principalmente durante as refeições e até 2 horas antes de dormir.\n\nDe 2 a 5 anos: O tempo de exposição às telas deve ser limitado a 1 hora por dia. Crianças dessa faixa etária devem ser mais protegidas da violência virtual, pois não sabem separar fantasia de realidade.\n\nAté 10 anos: Devem ter acesso controlado a computadores e dispositivos móveis. Crianças de até 10 anos não devem usar TV ou computador no próprio quarto.\n\nDisponível em: https://tab.uol.com.br. Acesso em: 25 ago. 2017 (adaptado)."}, "after": {"support_image": "/enem-2022/q016-review-20261025-1.png", "support": ""}, "reasons": ["Recorte completo refeito no caderno oficial: figuras e legendas preservadas.", "Infográfico único completo com o texto original integrado."]}, {"slug": "enem-2022", "number": 50, "id": "97858a60-5e75-4f22-98cc-d8177aa0fe09", "before": {"support_image": "/enem-2022/q050-support-1-1.png"}, "after": {"support_image": "/enem-2022/q050-review-20261025-1.png"}, "reasons": ["Recorte completo refeito no caderno oficial: figuras e legendas preservadas."]}, {"slug": "enem-2022", "number": 67, "id": "ca4b8a59-c41c-4ef4-97dc-5e0c805f44c2", "before": {"support_image": "/enem-2022/q067-support-1-1.png"}, "after": {"support_image": "/enem-2022/q067-review-20261025-1.png"}, "reasons": ["Recorte completo refeito no caderno oficial: figuras e legendas preservadas."]}, {"slug": "enem-2022", "number": 75, "id": "ead646e1-b2a6-46d7-b8d3-8486e2fc5487", "before": {"support_image": "/enem-2022/q075-support-1-1.png"}, "after": {"support_image": "/enem-2022/q075-review-20261025-1.png"}, "reasons": ["Recorte completo refeito no caderno oficial: figuras e legendas preservadas."]}, {"slug": "enem-2022", "number": 95, "id": "c21a29ec-a118-4fa6-9c15-391825b89dbb", "before": {"support_image": "/enem-2022/q095-support-1-1.png,/enem-2022/q095-support-1-2.png"}, "after": {"support_image": "/enem-2022/q095-review-20261025-1.png,/enem-2022/q095-review-20261025-2.png"}, "reasons": ["Recorte completo refeito no caderno oficial: figuras e legendas preservadas."]}, {"slug": "enem-2022", "number": 102, "id": "d1669d1c-b9b0-4a31-86b