ttps://raw.githubusercontent.com/piresramon/gpt-4-enem/main/data/figures/2024/questao_180_fileoutpart109.png,\r\nhttps://raw.githubusercontent.com/piresramon/gpt-4-enem/main/data/figures/2024/questao_180_fileoutpart107.png,\r\nhttps://raw.githubusercontent.com/piresramon/gpt-4-enem/main/data/figures/2024/questao_180_fileoutpart104.png,\r\nhttps://raw.githubusercontent.com/piresramon/gpt-4-enem/main/data/figures/2024/questao_180_fileoutpart105.png,https://raw.githubusercontent.com/piresramon/gpt-4-enem/main/data/figures/2024/questao_180_fileoutpart106.png,https://raw.githubusercontent.com/piresramon/gpt-4-enem/main/data/figures/2024/questao_180_fileoutpart108.png"}, "after": {"support_image": "https://raw.githubusercontent.com/piresramon/gpt-4-enem/main/data/figures/2024/questao_180_fileoutpart103.png,https://raw.githubusercontent.com/piresramon/gpt-4-enem/main/data/figures/2024/questao_180_fileoutpart109.png,https://raw.githubusercontent.com/piresramon/gpt-4-enem/main/data/figures/2024/questao_180_fileoutpart107.png,https://raw.githubusercontent.com/piresramon/gpt-4-enem/main/data/figures/2024/questao_180_fileoutpart104.png,https://raw.githubusercontent.com/piresramon/gpt-4-enem/main/data/figures/2024/questao_180_fileoutpart105.png,https://raw.githubusercontent.com/piresramon/gpt-4-enem/main/data/figures/2024/questao_180_fileoutpart106.png,https://raw.githubusercontent.com/piresramon/gpt-4-enem/main/data/figures/2024/questao_180_fileoutpart108.png"}, "reasons": ["Normaliza separadores e caminho local das imagens."]}]$enem_review$::jsonb) loop
    select id into expected_exam from public.exams where slug = item->>'slug';
    select * into current_row from public.questions
      where id = (item->>'id')::uuid and exam_id = expected_exam and number = (item->>'number')::int for update;
    if not found then raise exception 'Questão não encontrada: %/%', item->>'slug', item->>'number'; end if;
    if exists (select 1 from jsonb_each(item->'before') old
      where to_jsonb(current_row)->old.key is distinct from old.value
        and to_jsonb(current_row)->old.key is distinct from item->'after'->old.key)
      then raise exception 'Conteúdo alterado após a revisão: %/%', item->>'slug', item->>'number'; end if;
    update public.questions set
      text = case when item->'after' ? 'text' then item->'after'->>'text' else text end,
      support = case when item->'after' ? 'support' then item->'after'->>'support' else support end,
      support_image = case when item->'after' ? 'support_image' then item->'after'->>'support_image' else support_image end
      where id = current_row.id;
  end loop;
end $review$;
commit;
